#!/usr/bin/env python3
"""Conan test_package for jpegqs - packaged CLI tool plus static library.

Every assertion executed by test.sh runs a real artifact produced by
`conan create`:
  * the packaged `jpegqs` binary transcodes a JPEG generated by libjpeg,
  * a consumer program is linked against the packaged libjpegqs.a and then
    executed, proving the exported smoothing symbol resolves.
"""
import os

from conan import ConanFile

MAKEJPEG_C = r"""#include <stdio.h>
#include <jpeglib.h>

/* Write a 16x16 baseline RGB JPEG with the reference encoder, i.e. the very
 * libjpeg copy jpegqs was linked against. Proves the dependency is usable and
 * gives jpegqs a real DQT/DHT/SOS stream to work on. */
int main(void) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    JSAMPROW row[1];
    unsigned char pixels[16 * 3];
    int x, y;
    FILE *fh = fopen("src.jpg", "wb");
    if (!fh) {
        perror("fopen");
        return 1;
    }
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, fh);
    cinfo.image_width = 16;
    cinfo.image_height = 16;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    for (y = 0; y < 16; y++) {
        for (x = 0; x < 16; x++) {
            pixels[x * 3 + 0] = (unsigned char)(x * 16);
            pixels[x * 3 + 1] = (unsigned char)(y * 16);
            pixels[x * 3 + 2] = 128;
        }
        row[0] = pixels;
        jpeg_write_scanlines(&cinfo, row, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(fh);
    printf("MAKED src.jpg\n");
    return 0;
}
"""

CONSUMER_C = r"""#include <stdio.h>

/* do_quantsmooth is exported by libjpegqs.a; declared with a locally
 * compatible prototype so the reference is resolved against the packaged
 * archive without pulling jpeglib.h internals into this translation unit. */
extern int do_quantsmooth(void);

int main(void) {
    void *sym = (void *)do_quantsmooth;
    if (sym == 0) {
        printf("CONSUMER: null symbol\n");
        return 1;
    }
    printf("CONSUMER: do_quantsmooth resolved at %p\n", sym);
    return 0;
}
"""


class JpegqsTestConan(ConanFile):
    settings = "os", "compiler", "build_type", "arch"
    generators = "VirtualRunEnv"
    test_type = "explicit"

    def requirements(self):
        self.requires(self.tested_reference_str)
        # Consumers of libjpegqs.h need the public JPEG types from libjpeg.
        self.requires("libjpeg/10")

    @staticmethod
    def _abs(dep, paths):
        return [p if os.path.isabs(p) else os.path.join(dep.package_folder, p)
                for p in (paths or [])]

    def build(self):
        pkg = self.dependencies["jpegqs"]
        jpeg = self.dependencies["libjpeg"]
        q_inc = " ".join(["-I" + p for p in self._abs(pkg, pkg.cpp_info.includedirs)])
        q_lib = " ".join(["-L" + p for p in self._abs(pkg, pkg.cpp_info.libdirs)])
        j_inc = " ".join(["-I" + p for p in self._abs(jpeg, jpeg.cpp_info.includedirs)])
        j_lib = " ".join(["-L" + p for p in self._abs(jpeg, jpeg.cpp_info.libdirs)])
        execs = self.conf.get("tools.build:compiler_executables",
                              check_type=dict, default={})
        cc = execs.get("c") or "clang"
        src = self.source_folder
        for name, body in (("makejpeg.c", MAKEJPEG_C), ("consumer.c", CONSUMER_C)):
            with open(os.path.join(src, name), "w") as handle:
                handle.write(body)
        # R34: the test programs really link the artifacts under test.
        self.run("%s %s %s -o makejpeg makejpeg.c %s -ljpeg -lm" % (cc, j_inc, j_lib, j_lib),
                 cwd=src)
        self.run("%s %s %s %s %s -o consumer consumer.c -ljpegqs -ljpeg -lm"
                 % (cc, q_inc, j_inc, q_lib, j_lib), cwd=src)

    def test(self):
        pkg = self.dependencies["jpegqs"]
        bash = os.environ.get("CONFIG_SHELL", "/data/service/hnp/bin/bash")
        script = os.path.join(self.source_folder, "test.sh")
        self.run('%s "%s" "%s" "%s"'
                 % (bash, script, self.source_folder, pkg.package_folder),
                 env="conanrun")
